<script setup lang="ts">
import AppAlert from '@/components/ui/AppAlert.vue'
// Read-only tracker for sales generated by DeliveryService (guide §7.6/§19)
// - no "New" button, mirroring backend/apps/sales/views.py SaleViewSet's
// disabled create/update/destroy. The "Attribuer un client" entry point
// added below (feedback 2026-09-10) does NOT create a Sale directly - it's
// a shortcut to the existing assign-customer workflow (previously only
// reachable via Trajets & chargements -> Stock entreprise -> trip detail),
// which only earmarks a COMPANY_STOCK trip for a customer; the Sale itself
// is still created later, at delivery confirmation.
import { ref, computed, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import { createResourceApi } from '@/api/resource'
import { formatMoney, formatQuantity, formatUnitMoney } from '@/utils/currency'
import { saleResource } from './api'
import type { Sale, CustomerBrief, ProductBrief } from './types'
import { tripResource } from '@/modules/trips/api'
import type { Trip } from '@/modules/trips/types'
import { formatTruckPlates } from '@/modules/trips/formatTruckPlates'
import AssignCustomerForm from '@/modules/trips/AssignCustomerForm.vue'
import MonoValue from '@/components/ui/MonoValue.vue'
import Button from '@/components/ui/Button.vue'
import Modal from '@/components/ui/Modal.vue'

const { t } = useI18n()
const router = useRouter()
const auth = useAuthStore()

const sales = ref<Sale[]>([])
const customers = ref<CustomerBrief[]>([])
const products = ref<ProductBrief[]>([])
const loading = ref(false)
const error = ref('')

const filters = ref({ customer: '', product: '' })

const customerResource = createResourceApi<CustomerBrief>('/customers/')
const productResource = createResourceApi<ProductBrief>('/products/')

async function loadSales() {
  loading.value = true
  error.value = ''
  try {
    const params: Record<string, string> = {}
    if (filters.value.customer) params.customer = filters.value.customer
    if (filters.value.product) params.product = filters.value.product
    const data = await saleResource.list(params)
    sales.value = data.results
  } catch {
    error.value = t('sales.saleList.loadError')
  } finally {
    loading.value = false
  }
}

onMounted(async () => {
  const [customerData, productData] = await Promise.all([
    customerResource.list(),
    productResource.list(),
  ])
  customers.value = customerData.results
  products.value = productData.results
  await loadSales()
})

// Same "assign_customer" permission tier as the action on TripDetail.vue
// (backend/apps/accounts/permissions.py ACTION_MAP["assign_customer"] ->
// "edit" on the "operations" module).
const canAssignCustomer = computed(() => auth.can('operations', 'edit'))

const showAssignModal = ref(false)
const eligibleTrips = ref<Trip[]>([])
const loadingEligibleTrips = ref(false)
const selectedTrip = ref<Trip | null>(null)

// Same "Stock entreprise" definition as TripStatusBoard.vue's company-stock
// tab (physically arrived, matches the dashboard total) - narrowed here to
// trips that don't already have a client, since that's the only thing this
// picker is for.
async function openAssignModal() {
  showAssignModal.value = true
  selectedTrip.value = null
  loadingEligibleTrips.value = true
  try {
    const data = await tripResource.list()
    eligibleTrips.value = data.results.filter(
      (trip) =>
        trip.destination_type === 'COMPANY_STOCK' &&
        !trip.client &&
        (trip.status === 'ARRIVED_AT_COMPANY_STOCK' || trip.status === 'STOCKED'),
    )
  } finally {
    loadingEligibleTrips.value = false
  }
}

function closeAssignModal() {
  showAssignModal.value = false
  selectedTrip.value = null
}

function onCustomerAssigned() {
  const tripId = selectedTrip.value?.id
  closeAssignModal()
  if (tripId) router.push({ name: 'trip-detail', params: { id: tripId } })
}
</script>

<template>
  <div class="space-y-4">
    <div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <h1 class="font-display text-2xl leading-none font-semibold uppercase">
        {{ t('sales.saleList.title') }}
      </h1>
      <Button v-if="canAssignCustomer" variant="primary" @click="openAssignModal">
        {{ t('trips.assignCustomer.action') }}
      </Button>
    </div>

    <div class="flex flex-wrap gap-3">
      <select
        v-model="filters.customer"
        class="border-ligne-forte h-11 rounded-lg border bg-white px-3 text-sm"
        @change="loadSales"
      >
        <option value="">{{ t('sales.saleList.allCustomers') }}</option>
        <option v-for="c in customers" :key="c.id" :value="c.id">{{ c.name }}</option>
      </select>
      <select
        v-model="filters.product"
        class="border-ligne-forte h-11 rounded-lg border bg-white px-3 text-sm"
        @change="loadSales"
      >
        <option value="">{{ t('sales.saleList.allProducts') }}</option>
        <option v-for="p in products" :key="p.id" :value="p.id">{{ p.name }}</option>
      </select>
    </div>

    <AppAlert v-if="error" :message="error" />

    <div class="border-ligne overflow-x-auto rounded-xl border bg-white">
      <table class="w-full text-left text-sm">
        <thead>
          <tr class="border-ligne text-texte-2 border-b">
            <th class="px-3 py-2.5 font-medium">{{ t('sales.saleList.table.trip') }}</th>
            <th class="px-3 py-2.5 font-medium">{{ t('sales.saleList.table.customer') }}</th>
            <th class="px-3 py-2.5 font-medium">{{ t('sales.saleList.table.product') }}</th>
            <th class="px-3 py-2.5 text-right font-medium">
              {{ t('sales.saleList.table.delivered') }}
            </th>
            <th class="px-3 py-2.5 text-right font-medium">
              {{ t('sales.saleList.table.unitPrice') }}
            </th>
            <th class="px-3 py-2.5 text-right font-medium">
              {{ t('sales.saleList.table.subtotal') }}
            </th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="sale in sales"
            :key="sale.id"
            class="border-ligne hover:bg-sable border-b last:border-0"
          >
            <td class="px-3 py-2.5">
              <RouterLink
                class="text-texte-2 hover:text-texte underline decoration-dotted"
                :to="{ name: 'trip-detail', params: { id: sale.trip } }"
              >
                {{ sale.trip_reference }}
              </RouterLink>
            </td>
            <td class="px-3 py-2.5 font-medium">{{ sale.customer_detail?.name }}</td>
            <td class="px-3 py-2.5">{{ sale.product_detail?.name }}</td>
            <td class="px-3 py-2.5 text-right">
              <MonoValue :value="formatQuantity(sale.delivered_quantity)" />
            </td>
            <td class="px-3 py-2.5 text-right">
              <MonoValue :value="formatUnitMoney(sale.unit_selling_price)" />
            </td>
            <td class="px-3 py-2.5 text-right">
              <MonoValue :value="formatMoney(sale.subtotal)" />
            </td>
          </tr>
          <tr v-if="!loading && sales.length === 0">
            <td colspan="6" class="text-texte-3 px-3 py-8 text-center">
              {{ t('sales.saleList.noSales') }}
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <Modal
      v-if="showAssignModal"
      :title="t('trips.assignCustomer.action')"
      max-width="max-w-2xl"
      @close="closeAssignModal"
    >
      <AssignCustomerForm
        v-if="selectedTrip"
        :trip-id="selectedTrip.id"
        :trip-reference="selectedTrip.reference"
        @success="onCustomerAssigned"
        @cancel="selectedTrip = null"
      />
      <div v-else class="space-y-3">
        <p class="text-texte-2 text-sm">{{ t('trips.assignCustomer.pickTripHint') }}</p>
        <p v-if="loadingEligibleTrips" class="text-texte-3 text-sm">{{ t('common.loading') }}</p>
        <div v-else-if="!eligibleTrips.length" class="text-texte-3 text-sm">
          {{ t('trips.assignCustomer.noEligibleTrips') }}
        </div>
        <div v-else class="border-ligne max-h-96 divide-y overflow-y-auto rounded-lg border">
          <button
            v-for="trip in eligibleTrips"
            :key="trip.id"
            type="button"
            data-test="eligible-trip-row"
            class="hover:bg-sable flex w-full items-center justify-between gap-3 px-3 py-2.5 text-start text-sm"
            @click="selectedTrip = trip"
          >
            <span>
              <span class="text-texte font-medium">{{ trip.reference }}</span>
              <span class="text-texte-2"> · {{ formatTruckPlates(trip.truck_detail) }}</span>
            </span>
            <span class="text-texte-2">
              {{ trip.product_detail?.name }} ·
              <MonoValue :value="formatQuantity(trip.quantity_loaded)" />
            </span>
          </button>
        </div>
      </div>
    </Modal>
  </div>
</template>
